/// <summary>
/// PricingAttribute of table <c>RetailSalesTable</c> field TaxOverrideCode.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesTable, UPSPricingAttributeSourceLevel::Header)]
class UPSPricingAttributeRetailSalesTableTaxOverrideCode extends UPSPricingAttributeRetailSalesTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(RetailSalesTable, TaxOverrideCode);
}

public Set getAllowedValues()
{
    RetailSalesTable    retailSalesTable;
    var                 ret = new Set(Types::String);

    while select TaxOverrideCode from retailSalesTable
        group by TaxOverrideCode
    {
        ret.add(retailSalesTable.TaxOverrideCode);
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(RetailSalesTable, TaxOverrideCode));
    qbr.value(queryValue(_value));
}
